      "\u039C\u03B5\u03C4\u03B1\u03BC\u03BF\u03C3\u03C7\u03B5\u03C5\u03BC\u03AD\u03BD\u03BF\u03B9 (\u03B5\u03C0\u03B1\u03BD\u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 v357): \u03B5\u03C0\u03B1\u03BD\u03AE\u03BB\u03B8\u03B1\u03BD \u03BC\u03B5 \u03C0\u03B7\u03B3\u03AD\u03C2 \u2014 \u03C3\u03C5\u03BD\u03B5\u03BD\u03BD\u03CC\u03B7\u03C3\u03B7 \u03BC\u03B5 \u03C4\u03BF \u03BA\u03AD\u03BD\u03C4\u03C1\u03BF \u03BC\u03B5\u03C4\u03B1\u03BC\u03CC\u03C3\u03C7\u03B5\u03C5\u03C3\u03B7\u03C2, \u03B1\u03BB\u03BB\u03B1\u03B3\u03AE \u03BF\u03B4\u03BF\u03CD PO\u2192IV, \u03AC\u03C3\u03B7\u03C0\u03C4\u03B7 \u03C4\u03B5\u03C7\u03BD\u03B9\u03BA\u03AE \u03BA\u03B1\u03B9 \u03AC\u03C4\u03C5\u03C0\u03B1 \u03C3\u03B7\u03BC\u03B5\u03AF\u03B1 \u03BB\u03BF\u03AF\u03BC\u03C9\u03BE\u03B7\u03C2, \u03B9\u03C3\u03BF\u03C0\u03C1\u03B5\u03BD\u03B1\u03BB\u03AF\u03BD\u03B7/\u03B1\u03B4\u03C1\u03B5\u03BD\u03B1\u03BB\u03AF\u03BD\u03B7 \u03B3\u03B9\u03B1 \u03B2\u03C1\u03B1\u03B4\u03C5\u03BA\u03B1\u03C1\u03B4\u03AF\u03B1, \u03BC\u03BF\u03C3\u03C7\u03B5\u03C5\u03BC\u03AD\u03BD\u03BF\u03C2 \u03C0\u03BD\u03B5\u03CD\u03BC\u03BF\u03BD\u03B1\u03C2 \u03C7\u03C9\u03C1\u03AF\u03C2 \u03B2\u03AE\u03C7\u03B1 \u03BA\u03AC\u03C4\u03C9 \u03B1\u03C0\u03CC \u03C4\u03B7\u03BD \u03B1\u03BD\u03B1\u03C3\u03C4\u03CC\u03BC\u03C9\u03C3\u03B7, \u03BC\u03BF\u03C3\u03C7\u03B5\u03C5\u03BC\u03AD\u03BD\u03BF\u03C2 \u03BD\u03B5\u03C6\u03C1\u03CC\u03C2 (\u03C0\u03AF\u03B5\u03C3\u03B7 \u03B4\u03B9\u03AE\u03B8\u03B7\u03C3\u03B7\u03C2, \u03BD\u03B5\u03C6\u03C1\u03BF\u03C4\u03BF\u03BE\u03B9\u03BA\u03AC) (Choudhury 2017 \u00B7 Tomuli\u0107 Brusich & Acan 2018)\u00B7 \u03C5\u03C0\u03BF\u03BC\u03B1\u03B3\u03BD\u03B7\u03C3\u03B9\u03B1\u03B9\u03BC\u03AF\u03B1 \u03BA\u03B1\u03B9 \u03B1\u03C0\u03BF\u03C6\u03C5\u03B3\u03AE \u03C5\u03C0\u03B5\u03C1\u03B1\u03B5\u03C1\u03B9\u03C3\u03BC\u03BF\u03CD \u03BC\u03B5 \u03B1\u03BD\u03B1\u03C3\u03C4\u03BF\u03BB\u03B5\u03AF\u03C2 \u03BA\u03B1\u03BB\u03C3\u03B9\u03BD\u03B5\u03C5\u03C1\u03AF\u03BD\u03B7\u03C2\u00B7 \u03C0\u03B1\u03C1\u03B5\u03BD\u03AD\u03C1\u03B3\u03B5\u03B9\u03B5\u03C2 \u03BA\u03BF\u03C1\u03C4\u03B9\u03BA\u03BF\u03B5\u03B9\u03B4\u03CE\u03BD (SmPC \u03C0\u03C1\u03B5\u03B4\u03BD\u03B9\u03B6\u03BF\u03BB\u03CC\u03BD\u03B7\u03C2)\u00B7 \u03C3\u03B9\u03C1\u03CC\u03BB\u03B9\u03BC\u03BF\u03C5\u03C2 \u03BA\u03B1\u03B9 \u03B5\u03C0\u03BF\u03CD\u03BB\u03C9\u03C3\u03B7 (Rapamune)\u00B7 \u03B4\u03B5\u03BD \u03B5\u03C0\u03B1\u03BD\u03AE\u03BB\u03B8\u03B1\u03BD: \u00AB\u03C0\u03B1\u03C1\u03B1\u03C4\u03B5\u03AF\u03BD\u03BF\u03C5\u03BD \u03C4\u03B1 \u03BC\u03C5\u03BF\u03C7\u03B1\u03BB\u03B1\u03C1\u03C9\u03C4\u03B9\u03BA\u03AC\u00BB (\u03B4\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9 \u03C3\u03C4\u03B9\u03C2 \u03B5\u03C0\u03B9\u03C3\u03B7\u03BC\u03AC\u03BD\u03C3\u03B5\u03B9\u03C2) \u03BA\u03B1\u03B9 \u00AB\u03C4\u03BF \u03BA\u03AD\u03BD\u03C4\u03C1\u03BF \u03C3\u03C5\u03C7\u03BD\u03AC \u03C4\u03B1 \u03B4\u03B9\u03B1\u03BA\u03CC\u03C0\u03C4\u03B5\u03B9\u00BB",
      "\u039A\u03BB\u03AF\u03BC\u03B1\u03BA\u03B5\u03C2 \u03C0\u03CC\u03BD\u03BF\u03C5: FLACC \u03B5\u03C0\u03B9\u03BA\u03C5\u03C1\u03C9\u03BC\u03AD\u03BD\u03B7 \u03C3\u03B5 2 \u03BC\u03B7\u03BD\u03CE\u03BD \u2013 7 \u03B5\u03C4\u03CE\u03BD (Merkel 1997)\u00B7 \u03B1\u03BD\u03C4\u03AF \u03B3\u03B9\u03B1 \u03C4\u03BF \u00AB\u03BA\u03B1\u03C4\u03CE\u03C6\u03BB\u03B9 \u22654\u00BB \u03C0\u03BF\u03C5 \u03B4\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5, \u03B7 \u03BF\u03B4\u03B7\u03B3\u03AF\u03B1 \u03C4\u03BF\u03C5 University of Michigan: \u03C4\u03BF \u03C3\u03BA\u03BF\u03C1 \u03BD\u03B1 \u03BC\u03B7\u03BD \u03BA\u03B1\u03B8\u03BF\u03B4\u03B7\u03B3\u03B5\u03AF \u03BC\u03CC\u03BD\u03BF \u03C4\u03BF\u03C5 \u03C4\u03B7 \u03C6\u03B1\u03C1\u03BC\u03B1\u03BA\u03B5\u03C5\u03C4\u03B9\u03BA\u03AE \u03B1\u03B3\u03C9\u03B3\u03AE\u00B7 \u03BF\u03B9 \u03B8\u03B5\u03C1\u03B1\u03C0\u03B5\u03C5\u03C4\u03B9\u03BA\u03AD\u03C2 \u03BF\u03B4\u03B7\u03B3\u03AF\u03B5\u03C2 \u03B1\u03BD\u03AC NRS \u03BA\u03B1\u03B9 \u03B7 \u03C0\u03B1\u03BB\u03B9\u03AC \u03C0\u03B1\u03C1\u03B1\u03C0\u03BF\u03BC\u03C0\u03AE VO\u2082 \u03C4\u03BF\u03C5 Fick \u03B4\u03B5\u03BD \u03B5\u03C0\u03B1\u03BD\u03AE\u03BB\u03B8\u03B1\u03BD"
