    synEl: "\u03BD\u03C4\u03BF\u03C0\u03B1\u03BC\u03AF\u03BD\u03B7 \u03B4\u03BF\u03C0\u03B1\u03BC\u03AF\u03BD\u03B7",
    name: "Dopamine",
