    synEl: "\u03B5\u03C6\u03B5\u03B4\u03C1\u03AF\u03BD\u03B7 \u03C5\u03C0\u03CC\u03C4\u03B1\u03C3\u03B7 \u03C1\u03B1\u03C7\u03B9\u03B1\u03AF\u03B1",
    name: "Ephedrine",
