      "\u0391\u03BD\u03B1\u03C3\u03C4\u03C1\u03BF\u03C6\u03AE: \u03BD\u03B1\u03BB\u03BF\u03BE\u03CC\u03BD\u03B7, \u03C6\u03BB\u03BF\u03C5\u03BC\u03B1\u03B6\u03B5\u03BD\u03AF\u03BB\u03B7, sugammadex/\u03BD\u03B5\u03BF\u03C3\u03C4\u03B9\u03B3\u03BC\u03AF\u03BD\u03B7 \u03BA\u03B1\u03C4\u03AC \u03C0\u03B5\u03C1\u03AF\u03C0\u03C4\u03C9\u03C3\u03B7",
      "\u039C\u03B5\u03C4\u03B1\u03B2\u03BF\u03BB\u03B9\u03BA\u03AC: \u03C5\u03C0\u03BF\u03B3\u03BB\u03C5\u03BA\u03B1\u03B9\u03BC\u03AF\u03B1, \u03C5\u03C0\u03BF\u03B8\u03B5\u03C1\u03BC\u03AF\u03B1, Na+/\u03B7\u03BB\u03B5\u03BA\u03C4\u03C1\u03BF\u03BB\u03CD\u03C4\u03B5\u03C2, \u03C5\u03C0\u03B5\u03C1\u03BA\u03B1\u03C0\u03BD\u03AF\u03B1",
